mapper.delete:
DELETE FROM post_reactions
 WHERE post_id = #{postId}
   AND user_id = #{userId}
   AND type    = #{type}

mapper.update:
UPDATE posts
   SET like_count = (SELECT COUNT(*)
                       FROM post_reactions
                      WHERE post_id = #{postId}
                        AND type    = 'LIKE')
 WHERE id = #{postId}

mapper.select:
SELECT type
  FROM post_reactions
 WHERE post_id = #{postId}
   AND user_id = #{userId}
